// Des: Drive one tab: open pages, find items, click points
// Flo: enable CDP domains > navigate and settle > read accessibility tree > match role + label (exact name first, then part of a name, any language case) > scroll into view > box centre
// I/O: Conn (caller) + URL, role, label list > page text, backend node id, x/y point
// ===================================================================
const std = @import("std"); const mem = std.mem; const cdp = @import("nt-brow-cdpz.zig"); const fld = @import("ut-text-fold.zig");
const CF = .{ .sigj = "(function(){var n=0,b=0;function s(d){if(!d||!d.body)return;n+=d.body.innerText.length;var a=d.querySelectorAll('[role=alertdialog],[aria-busy=true]');for(var i=0;i<a.length;i++){var t=(a[i].getAttribute('aria-label')||a[i].innerText||'');if(/loading/i.test(t)||a[i].getAttribute('aria-busy')==='true')b=1}var f=d.querySelectorAll('iframe');for(var j=0;j<f.length;j++){try{s(f[j].contentDocument)}catch(e){}}}s(document);return b?-Date.now():n})()", .txtj ="(function(){var t=document.body?document.body.innerText:'';var f=document.querySelectorAll('iframe');for(var i=0;i<f.length;i++){try{var d=f[i].contentDocument;if(d&&d.body)t+=String.fromCharCode(10)+d.body.innerText}catch(e){}}return t})()", .step = 250, .calm = 2, .doms = [_][]const u8{ "Page.enable", "Runtime.enable", "DOM.enable", "Accessibility.enable" } };
pub const Pt = struct { x: f64, y: f64 };
pub const Page = struct { conn: *cdp.Conn, gpaz: std.mem.Allocator, iozz: std.Io, dead: i64 = 0, mx: f64 = 0, my: f64 = 0,
pub fn arm(self: *Page, mill: u32) void { self.dead = cdp.nowMs(self.iozz) + mill; }
pub fn left(self: *Page) u32 { const rem = self.dead - cdp.nowMs(self.iozz); return if (rem <= 0) 0 else @intCast(rem); }
pub fn call(self: *Page, aren: std.mem.Allocator, mth: []const u8, prm: []const u8) !std.json.Value { return self.conn.callJson(aren, mth, prm, @max(self.left(), 1)); }
pub fn nap(self: *Page, mill: u32) void { std.Io.sleep(self.iozz, .fromMilliseconds(@min(mill, self.left())), .awake) catch {}; }
pub fn evalVal(self: *Page, aren: std.mem.Allocator, expr: []const u8) !std.json.Value { const prm = try std.json.Stringify.valueAlloc(aren, .{ .expression = expr, .returnByValue = true, .awaitPromise = true }, .{}); const res = try self.call(aren, "Runtime.evaluate", prm); if (res != .object) return error.CdpError; if (res.object.get("exceptionDetails") != null) return error.EvalFail; const out = res.object.get("result") orelse return error.CdpError; if (out != .object) return error.CdpError; return out.object.get("value") orelse .null; }
pub fn evalStr(self: *Page, aren: std.mem.Allocator, expr: []const u8) ![]const u8 { const val = try self.evalVal(aren, expr); return switch (val) { .string => |txt| txt, .integer => |num| try std.fmt.allocPrint(aren, "{d}", .{num}), .bool => |flg| if (flg) "true" else "false", else => "" }; }
pub fn evalNum(self: *Page, aren: std.mem.Allocator, expr: []const u8) i64 { const val = self.evalVal(aren, expr) catch return -1; return switch (val) { .integer => |num| num, .float => |flt| @intFromFloat(flt), .bool => |flg| if (flg) 1 else 0, else => 0 }; }
pub fn enable(self: *Page, aren: std.mem.Allocator) !void { for (CF.doms) |mth| _ = try self.call(aren, mth, ""); }
pub fn settle(self: *Page, aren: std.mem.Allocator) void { var prev: i64 = -2; var same: u32 = 0; while (self.left() > 0) { const cur = self.evalNum(aren, CF.sigj); if (cur == prev) { same += 1; if (same >= CF.calm) return; } else same = 0; prev = cur; self.nap(CF.step); } }
pub fn navigate(self: *Page, aren: std.mem.Allocator, urlz: []const u8) !void { var from: usize = self.conn.evts.items.len; const prm = try std.json.Stringify.valueAlloc(aren, .{ .url = urlz }, .{}); const res = try self.call(aren, "Page.navigate", prm); if (res == .object) { if (res.object.get("errorText")) |et| { if (et == .string) std.debug.print("navigate: {s} {s}\n", .{ et.string, urlz }); return error.NavFail; } } _ = try self.conn.evWait(aren, "Page.loadEventFired", &from, @max(self.left(), 1)); self.settle(aren); }
pub fn urlNow(self: *Page, aren: std.mem.Allocator) ![]const u8 { return self.evalStr(aren, "location.href"); }
pub fn textNow(self: *Page, aren: std.mem.Allocator) ![]const u8 { return self.evalStr(aren, CF.txtj); }
fn frameIds(aren: std.mem.Allocator, node: std.json.Value, out: *std.ArrayList([]const u8), depth: u32) void { if (node != .object or depth > 4) return; if (depth > 0) { if (node.object.get("frame")) |frm| { if (frm == .object) { if (frm.object.get("id")) |idv| { if (idv == .string) out.append(aren, idv.string) catch return; } } } } if (node.object.get("childFrames")) |kids| { if (kids == .array) { for (kids.array.items) |kid| frameIds(aren, kid, out, depth + 1); } } }
fn nodesOf(res: std.json.Value, out: *std.ArrayList(std.json.Value), aren: std.mem.Allocator) !void { if (res != .object) return error.CdpError; const nodes = res.object.get("nodes") orelse return error.CdpError; if (nodes != .array) return error.CdpError; try out.appendSlice(aren, nodes.array.items); }
pub fn axNodes(self: *Page, aren: std.mem.Allocator) ![]const std.json.Value { var out: std.ArrayList(std.json.Value) = .empty; try nodesOf(try self.call(aren, "Accessibility.getFullAXTree", ""), &out, aren); const tre = self.call(aren, "Page.getFrameTree", "") catch return out.items; if (tre != .object) return out.items; var ids: std.ArrayList([]const u8) = .empty; if (tre.object.get("frameTree")) |ft| frameIds(aren, ft, &ids, 0); for (ids.items) |fid| { const prm = std.json.Stringify.valueAlloc(aren, .{ .frameId = fid }, .{}) catch continue; const sub = self.call(aren, "Accessibility.getFullAXTree", prm) catch continue; nodesOf(sub, &out, aren) catch continue; } return out.items; }
fn strOf(valu: ?std.json.Value) []const u8 { const vv = valu orelse return ""; if (vv != .object) return ""; const inn = vv.object.get("value") orelse return ""; return if (inn == .string) inn.string else ""; }
pub fn axFind(self: *Page, aren: std.mem.Allocator, role: []const u8, labs: []const []const u8, nth: usize) !?i64 { const nodes = try self.axNodes(aren); var lows = try aren.alloc([]u8, labs.len); for (labs, 0..) |lab, ix| lows[ix] = try fld.foldAlloc(aren, mem.trim(u8, lab, " ")); var exa: std.ArrayList(i64) = .empty; var sub: std.ArrayList(i64) = .empty; for (nodes) |nod| { if (nod != .object) continue; if (nod.object.get("ignored")) |ign| { if (ign == .bool and ign.bool) continue; } if (role.len > 0 and !mem.eql(u8, strOf(nod.object.get("role")), role)) continue; const bid = nod.object.get("backendDOMNodeId") orelse continue; if (bid != .integer) continue; const nam = strOf(nod.object.get("name")); if (nam.len == 0) continue; const lown = try fld.foldAlloc(aren, mem.trim(u8, nam, " ")); var hit = labs.len == 0; var exact = false; for (lows) |lw| { if (lw.len == 0) continue; if (mem.eql(u8, lown, lw)) { exact = true; hit = true; } else if (mem.find(u8, lown, lw) != null) hit = true; } if (!hit) continue; if (exact) try exa.append(aren, bid.integer); try sub.append(aren, bid.integer); } const pick = if (exa.items.len > 0) exa.items else sub.items; if (nth < pick.len) return pick[nth]; return null; }
pub fn axCount(self: *Page, aren: std.mem.Allocator, role: []const u8, labs: []const []const u8) !usize { var cnt: usize = 0; while (cnt < 10000) : (cnt += 1) { if ((try self.axFind(aren, role, labs, cnt)) == null) break; } return cnt; }
pub fn scrollInto(self: *Page, aren: std.mem.Allocator, bid: i64) !void { const prm = try std.json.Stringify.valueAlloc(aren, .{ .backendNodeId = bid }, .{}); _ = try self.call(aren, "DOM.scrollIntoViewIfNeeded", prm); }
fn numOf(valu: std.json.Value) f64 { return switch (valu) { .integer => |num| @floatFromInt(num), .float => |flt| flt, else => 0 }; }
pub fn center(self: *Page, aren: std.mem.Allocator, bid: i64) !Pt { const prm = try std.json.Stringify.valueAlloc(aren, .{ .backendNodeId = bid }, .{}); const res = try self.call(aren, "DOM.getBoxModel", prm); if (res != .object) return error.CdpError; const mdl = res.object.get("model") orelse return error.CdpError; if (mdl != .object) return error.CdpError; const con = mdl.object.get("content") orelse return error.CdpError; if (con != .array or con.array.items.len < 8) return error.CdpError; var sx: f64 = 0; var sy: f64 = 0; var ix: usize = 0; while (ix < 8) : (ix += 2) { sx += numOf(con.array.items[ix]); sy += numOf(con.array.items[ix + 1]); } return .{ .x = sx / 4.0, .y = sy / 4.0 }; }
pub fn closeConn(self: *Page) void { self.conn.close(); } };
pub fn pageOpen(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, wspath: []const u8, mill: u32) !Page { const conn = try cdp.connect(gpaz, iozz, port, wspath, mill); return .{ .conn = conn, .gpaz = gpaz, .iozz = iozz }; }
